    //   \[116..124) gid      (octal or GNU binary)  ← overflow field
    //   \[124..136) size     (octal)
    //   \[136..148) mtime    (octal)
    //   \[148..156) checksum
    //   \[156\]      typeflag ('0' = regular file)
    //   \[257..263) magic    ("ustar\\0")
    //   \[263..265) version  ("00")

